 Click(w,"显示项目");foreach(var exp in Tree(w).OfType<Expander>().ToArray())exp.IsExpanded=true;Pump();scroll.ScrollToTop();Pump();var child=Named<TextBox>(w,"标签-cpu");for(int i=0;i<240;i++){child.RaiseEvent(new MouseWheelEventArgs(Mouse.PrimaryDevice,Environment.TickCount,-120){RoutedEvent=UIElement.PreviewMouseWheelEvent});if(i%3==0)Pump();}Pump();Console.WriteLine("SCROLL offset="+scroll.VerticalOffset+" max="+scroll.ScrollableHeight+" viewport="+scroll.ViewportHeight+" source="+child.IsVisible);Check(Math.Abs(scroll.VerticalOffset-scroll.ScrollableHeight)<1,"wheel reaches bottom even over nested text editor");var apply=Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)=="应用并保存任务栏外观");var pos=apply.TranslatePoint(new Point(),scroll);Check(pos.Y>=0&&pos.Y+apply.ActualHeight<=scroll.ViewportHeight+1,"save action reachable at page bottom");Shot(w,Path.Combine(args[0],"taskbar-items-bottom.png"));
 w.ShowPage("下班倒计时");Pump();Check((string)Get(w,"page")=="侦探备忘录"&&Named<TextBox>(w,"下班提醒时间点")!=null,"legacy schedule entry opens unified memo editor");Click(w,"资源预警");Check(Tree(w).OfType<Expander>().Count()>=8,"all resource rules in expandable sections");Shot(w,Path.Combine(args[0],"memo-resource.png"));Click(w,"额度与重置");var five=Named<TextBox>(w,"五小时剩余额度（%）预警点");five.Text="5,10,25";Named<TextBox>(w,"重置前提醒（分钟）预警点").Text="1,8,30";Click(w,"保存额度与重置提醒");Check(assistant.Config.Monitor.Quota.FiveHourThresholds.SequenceEqual(new[]{5d,10d,25d})&&assistant.Config.Monitor.Quota.ResetReminderPoints.SequenceEqual(new[]{1,8,30}),"memo quota and multiple reset offsets persist");Shot(w,Path.Combine(args[0],"memo-quota.png"));foreach(string tab in new[]{"提醒","健康","专注","待办计划","文件观察","进程监控","Codex状态","系统通知","通知记录"}){Click(w,tab);Check(Tree(w).OfType<FrameworkElement>().Any(),"memo tab opens "+tab);}Click(w,"健康");Named<TextBox>(w,"健康提前提醒（分钟）预警点").Text="1,3,5";Click(w,"保存健康提前提醒点");Check(((SkillRuntime)Get(pet,"skills")).Engine.Data.WellnessAdvanceMinutes.SequenceEqual(new[]{1,3,5}),"health points saved from consolidated page");
 w.ShowPage("任务栏外观");Click(w,"布局与屏幕");assistant.Config.Monitor.Taskbar=true;Call(pet,"RefreshMonitorWindows");var mirrors=(System.Collections.IDictionary)Get(pet,"taskbarMirrors");Check(mirrors.Count==System.Windows.Forms.Screen.AllScreens.Length-1,"runtime monitor view count matches physical topology");var views=new List<TaskbarMonitor>{(TaskbarMonitor)Get(pet,"taskbarMonitor")};foreach(TaskbarMonitor view in mirrors.Values)views.Add(view);foreach(var view in views){string note;var shell=TaskbarMonitor.TaskbarFor(view.DisplayScreen,out note);Console.WriteLine("MONITOR "+view.DisplayScreen+" visible="+view.Visible+" status="+view.Status);Check(shell==IntPtr.Zero?!view.Visible:view.Visible&&System.Windows.Forms.Screen.FromHandle(view.Handle).DeviceName==view.DisplayScreen,"native taskbar view uses matching screen "+view.DisplayScreen);}File.WriteAllText(Path.Combine(args[0],"native-monitors.json"),new JavaScriptSerializer().Serialize(views.Select(v=>new{screen=v.DisplayScreen,visible=v.Visible,status=v.Status}).ToArray()));assistant.Config.Monitor.TaskbarAllScreens=false;Call(pet,"RefreshMonitorWindows");Check(((System.Collections.IDictionary)Get(pet,"taskbarMirrors")).Count==0,"turning off simultaneous mode disposes secondary views");assistant.Config.Monitor.Taskbar=false;Call(pet,"RefreshMonitorWindows");
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"memo-layout-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,physical_screens=System.Windows.Forms.Screen.AllScreens.Length,real_user_settings_changed=false}));return failures==0?0:1;}
